    }

    public Iterator<K> iterator() {
        return new Iterator<K>() {
            Iterator<V> vi = reverseMap.keySet().iterator();

            Iterator<K> ki = new ArrayList<K>().iterator();

            public boolean hasNext() {
                return vi.hasNext() || ki.hasNext();
            }

            public K next() {
                if (hasNext()) {
